const priorYearsResult = `-- name: PriorYearsResult :one
SELECT coalesce(sum(b.debit - b.credit), 0)::numeric AS net
FROM ledger.balances b
JOIN ledger.accounts a ON a.id = b.account_id
WHERE b.company_id = $1 AND a.class >= 4 AND b.month < $2
`

type PriorYearsResultParams struct {
	CompanyID   uuid.UUID
	FiscalStart civil.Date
}

// Laba rugi tahun-tahun sebelumnya yang belum ditutup ke laba ditahan.
func (q *Queries) PriorYearsResult(ctx context.Context, arg PriorYearsResultParams) (money.Amount, error) {
	row := q.db.QueryRow(ctx, priorYearsResult, arg.CompanyID, arg.FiscalStart)
	var net money.Amount
	err := row.Scan(&net)
	return net, err
}

